/**
 * harness-descriptor — the record type of schema id `specstride.harness/1:descriptor`, annex C, §C.2.
 *
 * Generated by `scripts/types.mjs` from `schemas/harness-descriptor.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface HarnessDescriptor {
  /**
   * Version of the descriptor schema
   *
   * Type in words: Whole number; 1.
   */
  descriptorVersion: number;
  /**
   * Id of the harness, unique in the resolved registry
   *
   * Type in words: Lower-case text with digits and hyphens.
   */
  id: string;
  /**
   * Name for people
   *
   * Type in words: Text.
   */
  displayName?: string;
  /**
   * `cli`, `openai-chat`, `anthropic-messages`, or another registered kind
   *
   * Type in words: Member of an open set.
   */
  kind: string;
  provider?: {
    /**
     * Identity used for the diversity test and for the terms lookup
     *
     * Type in words: Text.
     */
    id: string;
    /**
     * Row of the terms-gate data, or null for unknown terms
     *
     * Type in words: Text, or null.
     */
    termsRef: string | null;
  };
  /**
   * Set by the loader: `adapter`, `bundled`, `user`, `detected`
   *
   * Type in words: Member of a closed set.
   */
  origin?: "adapter" | "bundled" | "user" | "detected";
  /**
   * How presence is established free of charge: variables whose presence counts; for `cli` the executable, how to read its version, which help text must be present, the configuration home
   *
   * Type in words: Record.
   */
  detect: Record<string, unknown>;
  auth?: {
    /**
     * Auth tiers offered: 1, 2 or both. 3 is never valid
     *
     * Type in words: List of whole numbers.
     */
    tiers: unknown[];
    /**
     * Secret reference, or null when the harness owns its login
     *
     * Type in words: Secret reference, or null.
     */
    credential: string | null;
    /**
     * `bearer`, `x-api-key`, `none`
     *
     * Type in words: Member of a closed set.
     */
    scheme?: "bearer" | "x-api-key" | "none";
    /**
     * A free read-only request and the statuses that mean an auth failure; redirects refused
     *
     * Type in words: Record, or `none`.
     */
    preflight?: Record<string, unknown>;
  };
  /**
   * Base address, path of the chat call, path of the model list
   *
   * Type in words: Record.
   */
  endpoint?: Record<string, unknown>;
  /**
   * Default model; whether the list is probed or declared; the context window with its source; the output cap with its source; how a model is selected
   *
   * Type in words: Record.
   */
  models: Record<string, unknown>;
  /**
   * Per role: whether supported, with the reason if not; for a critic: `toolless` (`structural`, `flag`, `config`, `none`), `readOnlyTools` (supported or not), `freshSession`
   *
   * Type in words: Map from role to record.
   */
  roles: Record<string, unknown>;
  /**
   * Per role, for `cli`: argument list as a list, how the prompt is given and its size limit, working directory, environment, permission mechanism, files to write before the call
   *
   * Type in words: Map from role to record.
   */
  invoke?: Record<string, unknown>;
  stream?: {
    /**
     * `text`, `jsonl`, `sse-openai`, `sse-anthropic`, or a registered tested format
     *
     * Type in words: Member of an open set.
     */
    format: string;
    /**
     * Irregularities to accept
     *
     * Type in words: List of text.
     */
    tolerate?: unknown[];
    /**
     * Where input, output and cache tokens are found
     *
     * Type in words: Record of field paths.
     */
    usage?: Record<string, unknown>;
    /**
     * A data mapping from the harness's records to the six normalized records of §C.5: selector of the record kind and field paths
     *
     * Type in words: Record.
     */
    mapping?: Record<string, unknown>;
    /**
     * Name of a row of the dialect table of §C.5
     *
     * Type in words: Text.
     */
    dialect?: string;
  };
  /**
   * Whether supported, how an id is given, and `cacheTtlSec`, the cache lifetime of a session in seconds (300 where none is declared)
   *
   * Type in words: Record.
   */
  continuation: Record<string, unknown>;
  /**
   * Where session state lives and how it is redirected
   *
   * Type in words: Record.
   */
  session?: Record<string, unknown>;
  /**
   * The model-tier ladder of the harness, lowest first
   *
   * Type in words: List of records.
   */
  tiers?: unknown[];
  /**
   * Map from the typed failure vocabulary of §C.1 to what signals it: statuses, body patterns, exit codes, stream records
   *
   * Type in words: Map.
   */
  failures: Record<string, unknown>;
  /**
   * Class (`subscription`, `metered`, `local`, `unknown`) and prices with their date, or null
   *
   * Type in words: Record.
   */
  cost: Record<string, unknown>;
  isolation?: {
    /**
     * The only variables handed to a call
     *
     * Type in words: List of text.
     */
    envAllow: unknown[];
    /**
     * Variables and seeds of an overlay (§C.16)
     *
     * Type in words: Record.
     */
    configHome?: Record<string, unknown>;
  };
  containment?: {
    /**
     * Highest containment level the harness can enforce, with provenance
     *
     * Type in words: Member of §C.15, with provenance.
     */
    ceiling: string;
  };
  /**
   * Whether the harness has native memory and how it is switched off
   *
   * Type in words: Record.
   */
  memory: Record<string, unknown>;
  telemetry?: {
    /**
     * Variables or flags that switch the harness's own telemetry off
     *
     * Type in words: Record.
     */
    off?: Record<string, unknown>;
  };
  /**
   * Whether several processes may run at once under one configuration home and one login, with separate session stores
   *
   * Type in words: Truth value with provenance, or null.
   */
  concurrentSessions?: boolean | null;
  /**
   * Whether a process-level spending limit can be set, and how
   *
   * Type in words: Record with provenance, or null.
   */
  spendLimit?: Record<string, unknown> | null;
  /**
   * The transports offered, each with auth tier and terms row
   *
   * Type in words: List of records.
   */
  transports?: unknown[];
  /**
   * Tested range and date; present only on a tested harness adapter
   *
   * Type in words: Text, date.
   */
  versionRange?: string;
  /**
   * Tested range and date; present only on a tested harness adapter
   *
   * Type in words: Text, date.
   */
  verifiedOn?: string;
}
